sql.where:
p.deleted = 0
AND p.audit_status = 'approved'
AND p.status = 'on_sale'

    AND p.title LIKE CONCAT('%', #{query.keyword}, '%')


    AND p.category_id = #{query.categoryId}


    AND p.price >= #{query.minPrice}


    AND p.price <= #{query.maxPrice}


    AND p.quality = #{query.quality}

mapper.select:
SELECT p.id, p.title, p.price, p.original_price, p.quality, p.category_id, c.name AS category_name, p.status, p.seller_id, u.nickname AS seller_nickname, p.view_count, p.favorite_count, p.create_time, (SELECT pi.url FROM product_image pi WHERE pi.product_id = p.id ORDER BY pi.sort ASC, pi.id ASC LIMIT 1) AS cover FROM product p LEFT JOIN category c ON p.category_id = c.id AND c.deleted = 0 LEFT JOIN user u ON p.seller_id = u.id AND u.deleted = 0 WHERE p.deleted = 0 AND p.seller_id = #{sellerId}
AND p.status = #{status}
ORDER BY p.create_time DESC, p.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM product
WHERE deleted = 0 AND seller_id = #{sellerId}

    AND status = #{status}

